ui.css:
.hud-panel { background: #fffaf2; padding: 3px 26px 7px; border-radius: 22px; box-shadow: 0 6px 16px rgba(58,48,96,.24), inset 0 -4px 0 rgba(150,130,180,.13); font: 800 32px/1.1 'Baloo 2', 'Nunito', system-ui, sans-serif; color: #3e3a58; }
.hud-label { font: 800 10px/1 'Nunito', sans-serif; color: #8f87ab; letter-spacing: 2.2px; }
.bar { position: relative; width: 230px; height: 28px; background: #f2e6e2; border: 4px solid #fffaf2; border-radius: 999px; box-shadow: 0 6px 16px rgba(58,48,96,.24), inset 0 2px 3px rgba(110,50,50,.16); overflow: hidden; }
.bar-fill { position: relative; height: 100%; background: linear-gradient(180deg, #ffa58a 0%, #f46d5d 55%, #dd5449 100%); border-radius: 999px; box-shadow: inset 0 -3px 0 rgba(120,20,20,.14); }
.bar-fill::after { content: ''; position: absolute; left: 14px; right: 8px; top: 3px; height: 5px; border-radius: 99px; background: rgba(255,255,255,.45); }
.bar-alt { height: 24px; background: #e9e3f1; border: 4px solid #fffaf2; border-radius: 999px; }
.bar-alt-fill { background: linear-gradient(90deg, #62dcb4, #6fd1d8 55%, #74c3f4); border-radius: 999px; }
.card { width: 226px; border-radius: 28px; background: linear-gradient(180deg, #fffefb, #fbf3e9); color: #3e3a58; box-shadow: 0 18px 36px rgba(40,30,80,.34), inset 0 -6px 0 rgba(150,130,190,.16); }
